function showToast(message) { const toast = document.querySelector('#toast'); toast.textContent = message; toast.classList.add('show'); clearTimeout(showToast.timer); showToast.timer = setTimeout(() => toast.classList.remove('show'), 3200); }
let pendingSaktiImport = null;
function refreshDashboard() { accountPage = 1; selectedDirectorate = 'all'; selectedCompositionScope = 'deputy'; selectedCompositionCategory = null; document.querySelector('#directorateSelect').value = 'all'; document.querySelector('#compositionScope').value = 'deputy'; renderKpis(); renderPerformance(); lineChart(); renderComposition(); renderCurrentMonth(); renderAttention(); renderAccounts(); }
const snapshotMonth = period => monthNames[String(period.label || '').split(' ')[0].toLowerCase()] || period.month;
const snapshotKey = period => `${period.year}-${String(snapshotMonth(period)).padStart(2,'0')}`;
const loadSnapshots = () => { if (window.SaktiCloud?.configured && !window.SaktiCloud.isAuthenticated()) return {}; try { const raw = JSON.parse(localStorage.getItem('saktiSnapshots')) || {}; const migrated = Object.fromEntries(Object.entries(raw).map(([key, value]) => [key, value?.dataset ? { sp2d: value, accrual: null } : { sp2d: value?.sp2d || null, accrual: value?.accrual || null }])); if (JSON.stringify(raw) !== JSON.stringify(migrated)) localStorage.setItem('saktiSnapshots', JSON.stringify(migrated)); return migrated; } catch { return {}; } };
const saveSnapshots = snapshots => localStorage.setItem('saktiSnapshots', JSON.stringify(snapshots));
const sortedSnapshotKeys = snapshots => Object.keys(snapshots).sort();
function validateSnapshotConsistency(dataset, snapshots) { const key = snapshotKey(dataset.period); const keys = sortedSnapshotKeys(snapshots).filter(item => item < key); const previous = keys.length ? snapshots[keys[keys.length - 1]] : null; const directoratePagu = dataset.directorates.reduce((sum, item) => sum + item.pagu, 0); const directorateCumulative = dataset.directorates.reduce((sum, item) => sum + item.realization, 0); const directorateRemaining = dataset.directorates.reduce((sum, item) => sum + item.remaining, 0); const executiveRemaining = dataset.executiveSummary.pagu - dataset.executiveSummary.realization; const tolerance = Math.max(1000, dataset.executiveSummary.pagu * 0.0001); const reconciled = Math.abs(directoratePagu - dataset.executiveSummary.pagu) <= tolerance && Math.abs(directorateCumulative - dataset.executiveSummary.realization) <= tolerance && Math.abs(directorateRemaining - executiveRemaining) <= tolerance; let crossMonth = null; if (previous) { const expectedCumulative = previous.dataset.executiveSummary.realization + dataset.executiveSummary.monthly; const difference = dataset.executiveSummary.realization - expectedCumulative; crossMonth = { previousLabel: previous.dataset.period.label, difference, pass: Math.abs(difference) <= tolerance, paguChanged: previous.dataset.executiveSummary.pagu !== dataset.executiveSummary.pagu }; if (!crossMonth.pass) console.warn('SAKTI cross-month consistency check failed', crossMonth); } return { reconciled, crossMonth }; }
function rebuildMonthlyProgress(snapshots, year) { monthlyProgress = monthShortNames.map((month, index) => { const snapshot = snapshots[`${year}-${String(index + 1).padStart(2,'0')}`]; return { month, value: snapshot ? snapshot.dataset.executiveSummary.realization / snapshot.dataset.executiveSummary.pagu * 100 : null }; }); }
function populateSnapshotFilters(snapshots, activeKey) { const keys = sortedSnapshotKeys(snapshots); if (!keys.length) return; const yearSelect = document.querySelector('#yearSelect'), monthSelect = document.querySelector('#monthSelect'); const activeYear = Number(activeKey.slice(0,4)); const years = [...new Set(keys.map(key => key.slice(0,4)))]; yearSelect.innerHTML = years.map(year => `<option value="${year}" ${Number(year) === activeYear ? 'selected' : ''}>${year}</option>`).join(''); const monthKeys = keys.filter(key => key.startsWith(`${yearSelect.value || activeYear}-`)); monthSelect.innerHTML = monthKeys.map(key => `<option value="${key}" ${key === activeKey ? 'selected' : ''}>${snapshots[key].dataset.period.label.split(' ')[0]}</option>`).join(''); }
function setActiveSnapshot(key) { const snapshots = loadSnapshots(); const snapshot = snapshots[key]; if (snapshot?.dataset) applySaktiDataset(snapshot.dataset, snapshot.filename, false); }
function applySaktiDataset(dataset, filename, persist = true) { let snapshots = loadSnapshots(); const key = snapshotKey(dataset.period); if (persist) { snapshots[key] = { dataset, filename, savedAt: new Date().toISOString() }; saveSnapshots(snapshots); } else if (!snapshots[key]) { snapshots[key] = { dataset, filename, savedAt: new Date().toISOString() }; } const consistency = validateSnapshotConsistency(dataset, snapshots); const previous = consistency.crossMonth; dataset.executiveSummary = { ...dataset.executiveSummary, change: previous ? dataset.executiveSummary.realization / dataset.executiveSummary.pagu * 100 - snapshots[sortedSnapshotKeys(snapshots).filter(item => item < key).at(-1)]?.dataset.executiveSummary.realization / snapshots[sortedSnapshotKeys(snapshots).filter(item => item < key).at(-1)]?.dataset.executiveSummary.pagu * 100 : null, comparisonText: previous ? `${previous.difference >= 0 ? '+' : ''}${(dataset.executiveSummary.realization / dataset.executiveSummary.pagu * 100 - snapshots[sortedSnapshotKeys(snapshots).filter(item => item < key).at(-1)].dataset.executiveSummary.realization / snapshots[sortedSnapshotKeys(snapshots).filter(item => item < key).at(-1)].dataset.executiveSummary.pagu * 100).toLocaleString('id-ID',{minimumFractionDigits:2,maximumFractionDigits:2})} poin vs ${previous.previousLabel}` : 'Data bulan sebelumnya belum tersedia' }; executiveSummary = dataset.executiveSummary; directorates = dataset.directorates; accountDetails = dataset.accountDetails; budgetComposition = dataset.budgetComposition; rebuildMonthlyProgress(snapshots, dataset.period.year); populateSnapshotFilters(snapshots, key); document.querySelector('#sidebarPeriod').textContent = dataset.period.label; document.querySelector('#activePeriod').textContent = `• ${dataset.period.label}`; document.querySelector('#updatedAt').textContent = `Terakhir diperbarui: ${new Date().toLocaleDateString('id-ID')}`; refreshDashboard(); }
function uploadStatus(message, type = '') { const status = document.querySelector('#uploadStatus'); status.textContent = message; status.className = `upload-status ${type}`; }
function closeUploadModal() { document.querySelector('#uploadModal').hidden = true; }
function renderUploadPreview(fileName, dataset, directorateCount, consistency) { const preview = document.querySelector('#uploadPreview'); preview.hidden = false; const crossMonth = consistency.crossMonth ? consistency.crossMonth.pass ? `Konsisten dengan ${consistency.crossMonth.previousLabel}${consistency.crossMonth.paguChanged ? ' • Pagu berubah' : ''}` : `Perlu cek konsistensi dengan ${consistency.crossMonth.previousLabel}` : 'Snapshot awal • belum ada pembanding'; preview.innerHTML = `<div><span>File</span><strong>${fileName}</strong></div><div><span>Satker</span><strong>${dataset.satker.code} – ${dataset.satker.name}</strong></div><div><span>Periode</span><strong>${dataset.period.label}</strong></div><div><span>Direktorat terbaca</span><strong>${directorateCount}</strong></div><div><span>Total Pagu</span><strong>${rupiah.format(dataset.executiveSummary.pagu)}</strong></div><div><span>Realisasi s.d. Periode</span><strong>${rupiah.format(dataset.executiveSummary.realization)} (${fmtPct(dataset.executiveSummary.realization / dataset.executiveSummary.pagu * 100)})</strong></div><div><span>Rekonsiliasi</span><strong>${consistency.reconciled ? 'Lulus' : 'Perlu diperiksa'}</strong></div><div><span>Lintas bulan</span><strong>${crossMonth}</strong></div>`; }
async function handleSaktiFile(file) { if (!file) return; const validExtension = /\.xlsx?$/.test(file.name.toLowerCase()); if (!validExtension) { uploadStatus('Format file tidak didukung. Pilih laporan .xlsx atau .xls.', 'error'); return; } pendingSaktiImport = null; document.querySelector('#applySaktiData').disabled = true; document.querySelector('#uploadPreview').hidden = true; uploadStatus(`Membaca ${file.name}…`, 'loading'); try { const result = await parseWorkbook(file); if (result.errors.length) { uploadStatus(result.errors[0], 'error'); return; } const snapshots = loadSnapshots(); const key = snapshotKey(result.dataset.period); const consistency = validateSnapshotConsistency(result.dataset, snapshots); if (!consistency.reconciled) { uploadStatus('Total laporan tidak dapat direkonsiliasi dengan total direktorat.', 'error'); return; } const replacing = Boolean(snapshots[key]); pendingSaktiImport = { dataset: result.dataset, filename: file.name, replacing }; renderUploadPreview(file.name, result.dataset, result.directorateCount, consistency); document.querySelector('#applySaktiData').textContent = replacing ? 'Ganti Snapshot' : 'Update Dashboard'; uploadStatus(replacing ? 'Snapshot periode ini sudah ada. Klik “Ganti Snapshot” untuk menggantinya.' : 'Laporan SAKTI tervalidasi dan siap digunakan.', 'success'); document.querySelector('#applySaktiData').disabled = false; } catch (error) { uploadStatus(error.message || 'File tidak dapat diproses. Pastikan ini laporan SAKTI yang valid.', 'error'); } }
function setupUploadModal() { const modal = document.querySelector('#uploadModal'), input = document.querySelector('#saktiFile'), dropZone = document.querySelector('#dropZone'); document.querySelector('#uploadButton').addEventListener('click', () => { modal.hidden = false; }); [document.querySelector('#uploadClose'), document.querySelector('#uploadCancel')].forEach(button => button.addEventListener('click', closeUploadModal)); modal.addEventListener('click', event => { if (event.target === modal) closeUploadModal(); }); input.addEventListener('change', event => handleSaktiFile(event.target.files[0])); ['dragenter','dragover'].forEach(type => dropZone.addEventListener(type, event => { event.preventDefault(); dropZone.classList.add('dragging'); })); ['dragleave','drop'].forEach(type => dropZone.addEventListener(type, event => { event.preventDefault(); dropZone.classList.remove('dragging'); })); dropZone.addEventListener('drop', event => handleSaktiFile(event.dataTransfer.files[0])); document.querySelector('#applySaktiData').addEventListener('click', () => { if (!pendingSaktiImport) return; applySaktiDataset(pendingSaktiImport.dataset, pendingSaktiImport.filename); closeUploadModal(); showToast('Data SAKTI berhasil memperbarui dashboard.'); }); }
function init(){ const select=document.querySelector('#directorateSelect'); select.innerHTML='<option value="all">Semua Direktorat</option>'+directorates.map(d=>`<option value="${d.id}">${d.name}</option>`).join(''); select.addEventListener('change',e=>setDirectorate(e.target.value)); const compositionSelect=document.querySelector('#compositionScope'); compositionSelect.innerHTML='<option value="deputy">Deputi HIS</option>'+directorates.map(d=>`<option value="${d.id}">${d.name}</option>`).join(''); compositionSelect.addEventListener('change',e=>{selectedCompositionScope=e.target.value;selectedCompositionCategory=null;renderComposition();}); document.querySelector('#compositionMetric').addEventListener('change',e=>{selectedCompositionMetric=e.target.value;selectedCompositionCategory=null;renderComposition();}); document.querySelectorAll('[data-performance-mode]').forEach(button=>button.addEventListener('click',()=>{performanceMode=button.dataset.performanceMode;document.querySelectorAll('[data-performance-mode]').forEach(item=>item.classList.toggle('active',item===button));renderPerformance();})); const accountDirectorate=document.querySelector('#accountDirectorate'); accountDirectorate.innerHTML='<option value="">Semua Direktorat</option>'+directorates.map(d=>`<option value="${d.id}">${d.name}</option>`).join(''); ['accountSearch','accountDirectorate','accountSort','accountPageSize'].forEach(id=>document.querySelector(`#${id}`).addEventListener(id === 'accountSearch' ? 'input' : 'change',event=>{accountPage=1;if(id==='accountPageSize')accountPageSize=Number(event.target.value);renderAccounts();})); document.querySelector('#accountPrevious').addEventListener('click',()=>{accountPage--;renderAccounts();}); document.querySelector('#accountNext').addEventListener('click',()=>{accountPage++;renderAccounts();}); document.querySelector('#detailBudgetButton').addEventListener('click',()=>showToast('Detail Anggaran akan tersedia pada modul berikutnya.')); document.querySelector('#resetButton').addEventListener('click',()=>setDirectorate('all')); document.querySelector('#pptButton').addEventListener('click',()=>showToast('Template PowerPoint akan tersedia pada modul berikutnya.')); setupUploadModal(); document.querySelector('#yearSelect').addEventListener('change',event=>{ const snapshots=loadSnapshots(); const key=sortedSnapshotKeys(snapshots).find(item=>item.startsWith(`${event.target.value}-`)); if(key)setActiveSnapshot(key); }); document.querySelector('#monthSelect').addEventListener('change',event=>{ if(event.target.value)setActiveSnapshot(event.target.value); }); try { let snapshots=loadSnapshots(); if(!Object.keys(snapshots).length){ const cached=JSON.parse(localStorage.getItem('hisSaktiDataset')); if(cached?.dataset?.rows?.length){ snapshots[snapshotKey(cached.dataset.period)]={dataset:cached.dataset,filename:cached.filename,savedAt:cached.savedAt}; saveSnapshots(snapshots); } } const keys=sortedSnapshotKeys(snapshots); if(keys.length) setActiveSnapshot(keys[keys.length-1]); else refreshDashboard(); } catch { refreshDashboard(); } }
function getMonthlyAbsorptionSeries(year, directorateId = 'all') { const snapshots = loadSnapshots(); return monthShortNames.map((label, index) => { const snapshot = snapshots[`${year}-${String(index + 1).padStart(2, '0')}`]?.dataset; if (!snapshot) return { month: index + 1, label, value: null }; const source = directorateId === 'all' ? snapshot.executiveSummary : snapshot.directorates?.find(item => (item.id || item.code || item.directorateCode) === directorateId); const value = source?.absorption ?? (source?.pagu > 0 ? (source.realization ?? source.cumulative ?? 0) / source.pagu * 100 : null); return { month: index + 1, label, value: Number.isFinite(value) ? value : null }; }); }
function lineChart() { const svg = document.querySelector('#lineChart'), width = 640, height = 230, left = 36, bottom = 34, top = 18, right = 12; const year = Number(document.querySelector('#yearSelect').value) || activeSnapshot?.period?.year; const series = year ? getMonthlyAbsorptionSeries(year, selectedDirectorate) : monthShortNames.map((label, index) => ({ month: index + 1, label, value: null })); const populated = series.filter(point => point.value !== null); const max = Math.max(55, ...populated.map(point => point.value + 5)); const x = i => left + i * ((width-left-right)/(series.length-1)), y = n => height-bottom - n/max*(height-top-bottom); const activeMonth = activeSnapshot?.period?.year === year ? activeSnapshot.period.month : null; const scopeLabel = selectedDirectorate === 'all' ? 'Deputi HIS' : (directorates.find(item => item.id === selectedDirectorate)?.name || selectedDirectorate); document.querySelector('#progressYear').textContent = year ? `TAHUN ${year} · ${scopeLabel}` : 'BELUM ADA DATA'; const activeValue = activeMonth ? series[activeMonth - 1]?.value : null; document.querySelector('#progressValue').textContent = activeValue === null || activeValue === undefined ? '—' : fmtPct(activeValue); let markup = ''; [0,20,40,60,80].filter(value => value <= max).forEach(value => { markup += `<line x1="${left}" x2="${width-right}" y1="${y(value)}" y2="${y(value)}" class="gridline"/><text x="0" y="${y(value)+4}" class="axis-label">${value}%</text>`; }); let run = []; const flushRun = () => { if (run.length > 1) markup += `<polyline points="${run.join(' ')}" class="line"/>`; run = []; }; series.forEach((point, index) => { if (point.value === null) flushRun(); else run.push(`${x(index)},${y(point.value)}`); }); flushRun(); series.forEach((point, index) => { if (point.value !== null) markup += `<circle cx="${x(index)}" cy="${y(point.value)}" r="${point.month === activeMonth ? 6 : 4}" class="point${point.month === activeMonth ? ' active-point' : ''}"/>`; markup += `<text x="${x(index)}" y="${height-8}" text-anchor="middle" class="axis-label">${point.label}</text>`; }); if (activeValue !== null && activeValue !== undefined) markup += `<text x="${x(activeMonth - 1)-8}" y="${y(activeValue)-12}" text-anchor="end" class="value-label">${fmtPct(activeValue)}</text>`; svg.innerHTML = markup; }
function refreshDashboard() { accountPage = 1; selectedCompositionScope = selectedDirectorate === 'all' ? 'deputy' : selectedDirectorate; selectedCompositionCategory = null; document.querySelector('#directorateSelect').value = selectedDirectorate; document.querySelector('#compositionScope').value = selectedCompositionScope; renderKpis(); renderPerformance(); lineChart(); renderComposition(); renderCurrentMonth(); renderAttention(); renderAccounts(); }
function setDirectorate(id) { selectedDirectorate = id; document.querySelector('#directorateSelect').value = id; selectedCompositionScope = id === 'all' ? 'deputy' : id; selectedCompositionCategory = null; document.querySelector('#compositionScope').value = selectedCompositionScope; renderComposition(); renderKpis(); renderPerformance(); lineChart(); }
function syncDirectorateOptions() { const options = directorates.map(d => `<option value="${d.id}">${d.name}</option>`).join(''); document.querySelector('#directorateSelect').innerHTML = '<option value="all">Semua Direktorat</option>' + options; document.querySelector('#compositionScope').innerHTML = '<option value="deputy">Deputi HIS</option>' + options; document.querySelector('#accountDirectorate').innerHTML = '<option value="">Semua Direktorat</option>' + options; }
function updateActivePeriod(period) { const label = period?.label || 'Belum ada data SAKTI'; document.querySelector('#sidebarPeriod').textContent = label; document.querySelector('#activePeriod').textContent = `• ${label}`; document.querySelector('#currentMonthPeriod').textContent = label; document.querySelector('#progressYear').textContent = period?.year ? `TAHUN ${period.year}` : 'BELUM ADA DATA'; document.querySelector('#updatedAt').textContent = activeSnapshot ? `Terakhir diperbarui: ${new Date().toLocaleDateString('id-ID')}` : 'Unggah laporan SAKTI untuk mulai'; }
function attentionRules(){ const average = executiveSummary.pagu ? executiveSummary.realization / executiveSummary.pagu * 100 : 0; const period = activeSnapshot?.period?.label || 'periode aktif'; return directorates.flatMap(d=>{ const msgs=[]; if(activeSnapshot && d.monthly === 0) msgs.push(`Tidak ada realisasi pada ${period}`); if(pct(d)<35 && d.monthly !== 0) msgs.push(`Serapan ${fmtPct(pct(d))}`); if(pct(d)<average-10 && !msgs.length) msgs.push(`Serapan di bawah rata-rata Eselon I (${fmtPct(average)})`); return msgs.map(message=>({name:d.name,message})); }); }
function applySaktiDataset(dataset, filename, persist = true) { let snapshots = loadSnapshots(); const key = snapshotKey(dataset.period); if (persist) { snapshots[key] = { dataset, filename, savedAt: new Date().toISOString() }; saveSnapshots(snapshots); } else if (!snapshots[key]) { snapshots[key] = { dataset, filename, savedAt: new Date().toISOString() }; } const consistency = validateSnapshotConsistency(dataset, snapshots); const previous = consistency.crossMonth; const previousKey = sortedSnapshotKeys(snapshots).filter(item => item < key).at(-1); const previousSummary = previousKey ? snapshots[previousKey].dataset.executiveSummary : null; const currentPct = dataset.executiveSummary.pagu ? dataset.executiveSummary.realization / dataset.executiveSummary.pagu * 100 : 0; const previousPct = previousSummary?.pagu ? previousSummary.realization / previousSummary.pagu * 100 : null; executiveSummary = { ...dataset.executiveSummary, change: previousPct === null ? null : currentPct - previousPct, comparisonText: previous ? `${(currentPct - previousPct >= 0 ? '+' : '')}${(currentPct - previousPct).toLocaleString('id-ID',{minimumFractionDigits:2,maximumFractionDigits:2})} poin vs ${previous.previousLabel}` : 'Data bulan sebelumnya belum tersedia' }; directorates = dataset.directorates; accountDetails = []; budgetComposition = {}; activeSnapshot = { ...dataset, filename }; rebuildMonthlyProgress(snapshots, dataset.period.year); syncDirectorateOptions(); populateSnapshotFilters(snapshots, key); updateActivePeriod(dataset.period); refreshDashboard(); }
function snapshotDataset(bucket, sourceType = 'sp2d') { return bucket?.[sourceType]?.dataset || null; }
function stableRowKey(row) { return [row.directorateCode, row.roCode, row.componentCode, row.subcomponentCode, row.accountCode].join('::'); }
function reconcileAccrual(sp2dDataset, accrualDataset) { const accrualRows = new Map((accrualDataset?.rows || []).map(row => [stableRowKey(row), row])); let matched = 0, accrualOnly = 0, lowerThanSp2d = 0, outstanding = 0; const rows = (sp2dDataset?.rows || []).map(row => { const accrual = accrualRows.get(stableRowKey(row)); if (accrual) { matched++; accrualRows.delete(stableRowKey(row)); } const rawDelta = accrual ? accrual.cumulative - row.cumulative : 0; if (rawDelta < 0) { lowerThanSp2d++; console.warn('SAKTI accrual reconciliation warning: accrual below SP2D', stableRowKey(row)); } const accrualOutstanding = Math.max(rawDelta, 0); outstanding += accrualOutstanding; return { ...row, accrualOutstanding, potential: row.cumulative + accrualOutstanding }; }); accrualRows.forEach(row => { accrualOnly++; const accrualOutstanding = Math.max(row.cumulative, 0); outstanding += accrualOutstanding; rows.push({ ...row, accrualOutstanding, potential: accrualOutstanding, sp2dOnly: false }); }); const sp2dOnly = (sp2dDataset?.rows || []).length - matched; const diagnostics = { matched, accrualOnly, sp2dOnly, lowerThanSp2d, totalSp2d: sp2dDataset?.executiveSummary?.realization || 0, totalAccrualReport: accrualDataset?.executiveSummary?.realization || 0, outstandingAccrual: outstanding, potentialRealization: (sp2dDataset?.executiveSummary?.realization || 0) + outstanding }; console.info('SAKTI accrual reconciliation', diagnostics); return { rows, diagnostics }; }
function aggregateAccrualForScope(rows, directorateId) { const scopeRows = directorateId === 'all' ? rows : rows.filter(row => row.directorateCode === directorateId); return scopeRows.reduce((sum, row) => ({ outstanding: sum.outstanding + row.accrualOutstanding, potential: sum.potential + row.potential }), { outstanding: 0, potential: 0 }); }
function populateSnapshotFilters(snapshots, activeKey) { const keys = sortedSnapshotKeys(snapshots).filter(key => snapshotDataset(snapshots[key])); if (!keys.length) return; const yearSelect = document.querySelector('#yearSelect'), monthSelect = document.querySelector('#monthSelect'), activeYear = Number(activeKey.slice(0, 4)); const years = [...new Set(keys.map(key => key.slice(0, 4)))]; yearSelect.innerHTML = years.map(year => `<option value="${year}" ${Number(year) === activeYear ? 'selected' : ''}>${year}</option>`).join(''); const monthKeys = keys.filter(key => key.startsWith(`${activeYear}-`)); monthSelect.innerHTML = monthKeys.map(key => `<option value="${key}" ${key === activeKey ? 'selected' : ''}>${snapshotDataset(snapshots[key]).period.label.split(' ')[0]}</option>`).join(''); }
function setActiveSnapshot(key) { const bucket = loadSnapshots()[key]; const sp2d = snapshotDataset(bucket); if (sp2d) applySaktiDataset(sp2d, bucket.sp2d.filename, false, 'sp2d'); }
function applySaktiDataset(dataset, filename, persist = true, sourceType = document.querySelector('#sourceType')?.value || 'sp2d') { const snapshots = loadSnapshots(), key = snapshotKey(dataset.period); snapshots[key] = snapshots[key] || { sp2d: null, accrual: null }; if (persist || !snapshots[key][sourceType]) { snapshots[key][sourceType] = { dataset, filename, savedAt: new Date().toISOString(), sourceType }; saveSnapshots(snapshots); } const bucket = snapshots[key], sp2d = snapshotDataset(bucket); if (!sp2d) { showToast('Simpan SP2D / Definitif terlebih dahulu sebagai data resmi periode ini.'); return; } const accrual = snapshotDataset(bucket, 'accrual'); const reconciliation = reconcileAccrual(sp2d, accrual); activeSnapshot = { ...sp2d, filename: bucket.sp2d.filename, sourceType: 'sp2d', accrualSnapshot: accrual, pairedRows: reconciliation.rows, accrualDiagnostics: reconciliation.diagnostics, provenance: { sp2d: bucket.sp2d, accrual: bucket.accrual } }; executiveSummary = { ...sp2d.executiveSummary, remaining: sp2d.executiveSummary.pagu - sp2d.executiveSummary.realization, comparisonText: 'Realisasi resmi berdasarkan SP2D' }; directorates = sp2d.directorates; accountDetails = []; budgetComposition = {}; syncDirectorateOptions(); populateSnapshotFilters(snapshots, key); updateActivePeriod(sp2d.period); refreshDashboard(); }
function renderKpis() { const d = selectedData(); const layer = aggregateAccrualForScope(activeSnapshot?.pairedRows || [], selectedDirectorate); const potentialPct = d.pagu ? layer.potential / d.pagu * 100 : 0; const cards = [['Total Pagu', d.pagu, 'Alokasi anggaran tahun berjalan', 'currency'], ['Realisasi SP2D s.d. Periode', d.realization, 'Realisasi resmi/definitif', 'currency'], ['% Serapan SP2D', d.percentage, 'Target kumulatif hingga periode aktif', 'percent'], ['Sisa Anggaran', d.remaining, 'Berdasarkan SP2D', 'currency'], ['Akrual Berjalan', layer.outstanding, activeSnapshot?.accrualSnapshot ? 'Dalam proses; belum definitif' : 'Akrual belum tersedia', 'currency']]; const normal = cards.map(([label, value, note, type]) => `<article class="kpi-card"><span class="kpi-label">${label}</span><strong class="kpi-value">${type === 'currency' ? rupiah.format(value) : fmtPct(value)}</strong><small>${note}</small></article>`).join(''); const potential = `<article class="kpi-card kpi-potential"><span class="kpi-label">Potensi Realisasi</span><strong class="kpi-value">${rupiah.format(layer.potential)}</strong><strong class="potential-percent">${fmtPct(potentialPct)}</strong><small>SP2D + akrual berjalan</small></article>`; document.querySelector('#kpiCards').innerHTML = normal + potential; }
async function handleSaktiFile(file) { if (!file || !/\.xlsx?$/.test(file.name.toLowerCase())) { uploadStatus('Pilih laporan .xlsx atau .xls.', 'error'); return; } const sourceType = document.querySelector('#sourceType').value; pendingSaktiImport = null; document.querySelector('#applySaktiData').disabled = true; uploadStatus(`Membaca ${file.name}…`, 'loading'); try { const result = await parseWorkbook(file); if (result.errors.length) throw new Error(result.errors[0]); const snapshots = loadSnapshots(), key = snapshotKey(result.dataset.period), replacing = Boolean(snapshots[key]?.[sourceType]); pendingSaktiImport = { dataset: result.dataset, filename: file.name, sourceType }; renderUploadPreview(file.name, result.dataset, result.directorateCount, { reconciled: true, crossMonth: null }); document.querySelector('#applySaktiData').textContent = replacing ? `Ganti ${sourceType === 'sp2d' ? 'SP2D' : 'Akrual'}` : 'Update Dashboard'; uploadStatus(replacing ? `Data ${sourceType === 'sp2d' ? 'SP2D' : 'Akrual'} periode ini sudah tersedia. Klik untuk mengganti hanya sumber tersebut.` : 'Laporan SAKTI tervalidasi dan siap digunakan.', 'success'); document.querySelector('#applySaktiData').disabled = false; } catch (error) { uploadStatus(error.message || 'File tidak dapat diproses.', 'error'); } }
function setupUploadModal() { const modal = document.querySelector('#uploadModal'), input = document.querySelector('#saktiFile'), dropZone = document.querySelector('#dropZone'); document.querySelector('#uploadButton').addEventListener('click', () => { modal.hidden = false; }); [document.querySelector('#uploadClose'), document.querySelector('#uploadCancel')].forEach(button => button.addEventListener('click', closeUploadModal)); modal.addEventListener('click', event => { if (event.target === modal) closeUploadModal(); }); input.addEventListener('change', event => handleSaktiFile(event.target.files[0])); dropZone.addEventListener('drop', event => { event.preventDefault(); handleSaktiFile(event.dataTransfer.files[0]); }); ['dragenter','dragover'].forEach(type => dropZone.addEventListener(type, event => event.preventDefault())); document.querySelector('#applySaktiData').addEventListener('click', () => { if (!pendingSaktiImport) return; applySaktiDataset(pendingSaktiImport.dataset, pendingSaktiImport.filename, true, pendingSaktiImport.sourceType); closeUploadModal(); showToast(`${pendingSaktiImport.sourceType === 'sp2d' ? 'SP2D' : 'Akrual'} berhasil diperbarui.`); }); }
function getMonthlyAbsorptionSeries(year, directorateId = 'all') { const snapshots = loadSnapshots(); return monthShortNames.map((label, index) => { const snapshot = snapshotDataset(snapshots[`${year}-${String(index + 1).padStart(2, '0')}`]); if (!snapshot) return { month: index + 1, label, value: null }; const source = directorateId === 'all' ? snapshot.executiveSummary : snapshot.directorates?.find(item => (item.id || item.code || item.directorateCode) === directorateId); const value = source?.absorption ?? (source?.pagu > 0 ? (source.realization ?? 0) / source.pagu * 100 : null); return { month: index + 1, label, value: Number.isFinite(value) ? value : null }; }); }
compositionMetricLabels.realization = 'Realisasi SP2D';
compositionMetricLabels.potential = 'Potensi Realisasi';
function potentialComposition() { const rows = activeSnapshot?.pairedRows || []; const scopes = { deputy: rows }; Object.keys(directorateCatalog).forEach(id => { scopes[id] = rows.filter(row => row.directorateCode === id); }); return Object.fromEntries(Object.entries(scopes).map(([scope, scopeRows]) => [scope, { categories: categoryDefinitions.map(definition => { const accounts = scopeRows.filter(row => accountCategory(row) === definition.category); return { category: definition.category, color: definition.color, pagu: accounts.reduce((sum, row) => sum + row.pagu, 0), realization: accounts.reduce((sum, row) => sum + row.cumulative, 0), potential: accounts.reduce((sum, row) => sum + row.potential, 0), remaining: accounts.reduce((sum, row) => sum + (row.pagu - row.cumulative), 0), accounts }; }) }])); }
function activeComposition() { return activeSnapshot?.rows?.length ? potentialComposition() : budgetComposition; }
function renderCompositionDetail() { const detail = document.querySelector('#compositionDetail'); const category = activeComposition()[selectedCompositionScope]?.categories.find(item => item.category === selectedCompositionCategory); if (!category || !category.accounts.length) { detail.hidden = true; detail.innerHTML = ''; return; } const isPotential = selectedCompositionMetric === 'potential'; detail.hidden = false; detail.innerHTML = `<div class="detail-heading"><div><span class="eyebrow">RINCIAN AKUN</span><h3>${category.category}</h3></div><button class="detail-close" type="button" aria-label="Tutup rincian kategori">×</button></div><div class="composition-table-scroll"><table><thead><tr><th>Akun</th><th>Uraian</th>${isPotential ? '<th>SP2D</th><th>Akrual Berjalan</th><th>Potensi</th>' : '<th>Pagu</th><th>Realisasi SP2D</th><th>Sisa</th>'}</tr></thead><tbody>${category.accounts.map(account => `<tr><td><strong>${account.accountCode}</strong></td><td>${account.accountName}</td>${isPotential ? `<td>${rupiah.format(account.cumulative)}</td><td>${rupiah.format(account.accrualOutstanding)}</td><td><strong>${rupiah.format(account.potential)}</strong></td>` : `<td>${rupiah.format(account.pagu)}</td><td>${rupiah.format(account.cumulative)}</td><td><strong>${rupiah.format(account.pagu - account.cumulative)}</strong></td>`}</tr>`).join('')}</tbody></table></div>`; detail.querySelector('.detail-close').addEventListener('click', () => { selectedCompositionCategory = null; renderCompositionDetail(); }); }
function renderComposition() { const unavailable = selectedCompositionMetric === 'potential' && !activeSnapshot?.accrualSnapshot; const categories = unavailable ? [] : (activeComposition()[selectedCompositionScope]?.categories || []); const total = categories.reduce((sum, category) => sum + category[selectedCompositionMetric], 0); let start = 0; document.querySelector('#donutSlices').innerHTML = categories.map(category => { const share = total ? category[selectedCompositionMetric] / total * 100 : 0; const end = start + share * 3.6; const path = `<path class="donut-slice ${selectedCompositionCategory === category.category ? 'selected' : ''}" data-category="${category.category}" d="${donutPath(start, end)}" fill="${category.color}" tabindex="0" role="button" aria-label="${category.category}: ${fmtPct(share)}"/>`; start = end; return path; }).join(''); document.querySelector('#compositionTotal').textContent = unavailable ? '—' : compact(total); document.querySelector('#compositionMetricLabel').textContent = unavailable ? 'Data akrual belum tersedia' : compositionMetricLabels[selectedCompositionMetric]; document.querySelector('#compositionLegend').innerHTML = unavailable ? '<span class="section-note">Data akrual belum tersedia</span>' : categories.map(category => { const share = total ? category[selectedCompositionMetric] / total * 100 : 0; return `<button class="legend-item ${selectedCompositionCategory === category.category ? 'selected' : ''}" type="button" data-category="${category.category}"><i style="background:${category.color}"></i><span>${category.category}</span><strong>${fmtPct(share)}</strong><small>${compact(category[selectedCompositionMetric])}</small></button>`; }).join(''); const chooseCategory = category => { selectedCompositionCategory = category; renderComposition(); renderCompositionDetail(); }; document.querySelectorAll('[data-category]').forEach(item => { item.addEventListener('click', () => chooseCategory(item.dataset.category)); item.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); chooseCategory(item.dataset.category); } }); }); renderCompositionDetail(); }
let yearlyView = null;
function enterYearlyView(year) { const snapshots = loadSnapshots(); const keys = sortedSnapshotKeys(snapshots).filter(key => key.startsWith(`${year}-`) && snapshotDataset(snapshots[key])); const key = keys.at(-1); if (!key) return; yearlyView = { year, latest: snapshotDataset(snapshots[key]).period }; const bucket = snapshots[key]; applySaktiDataset(snapshotDataset(bucket), bucket.sp2d.filename, false, 'sp2d'); document.querySelector('#monthSelect').value = 'yearly'; document.querySelector('#sidebarPeriod').textContent = `Tahunan ${year}`; document.querySelector('#activePeriod').textContent = `• Tahunan ${year} · s.d. ${yearlyView.latest.label}`; document.querySelector('#currentMonthPeriod').textContent = `Tahunan ${year}`; }
function populateSnapshotFilters(snapshots, activeKey) { const keys = sortedSnapshotKeys(snapshots).filter(key => snapshotDataset(snapshots[key])); if (!keys.length) return; const yearSelect = document.querySelector('#yearSelect'), monthSelect = document.querySelector('#monthSelect'), activeYear = Number(activeKey.slice(0, 4)); const years = [...new Set(keys.map(key => key.slice(0, 4)))]; yearSelect.innerHTML = years.map(year => `<option value="${year}" ${Number(year) === activeYear ? 'selected' : ''}>${year}</option>`).join(''); const monthKeys = keys.filter(key => key.startsWith(`${activeYear}-`)); monthSelect.innerHTML = monthKeys.map(key => `<option value="${key}">${snapshotDataset(snapshots[key]).period.label.split(' ')[0]}</option>`).join('') + '<option value="yearly">Tahunan</option>'; }
function setActiveSnapshot(key) { yearlyView = null; const bucket = loadSnapshots()[key]; const sp2d = snapshotDataset(bucket); if (sp2d) applySaktiDataset(sp2d, bucket.sp2d.filename, false, 'sp2d'); }
setTimeout(() => document.querySelector('#monthSelect').addEventListener('change', event => { if (event.target.value === 'yearly') enterYearlyView(Number(document.querySelector('#yearSelect').value)); }), 0);
function renderCurrentMonth() { const panel = document.querySelector('#currentMonth').closest('.panel'); const title = panel.querySelector('h2'); if (!yearlyView) { title.innerHTML = `Realisasi Bulan Ini <span>– <span id="currentMonthPeriod">${activeSnapshot?.period?.label || 'Belum ada data SAKTI'}</span></span>`; document.querySelector('#currentMonth').innerHTML = [...directorates].sort((a,b)=>b.monthly-a.monthly).map(d=>`<div class="month-row"><div><strong>${d.name}</strong><span>${d.id}</span></div><b>${compact(d.monthly)}</b></div>`).join(''); return; } title.innerHTML = 'Realisasi per Bulan <span>– SP2D periode berjalan</span>'; const snapshots = loadSnapshots(); const rows = sortedSnapshotKeys(snapshots).filter(key => key.startsWith(`${yearlyView.year}-`)).map(key => snapshotDataset(snapshots[key])).filter(Boolean).map(dataset => { const source = selectedDirectorate === 'all' ? dataset.executiveSummary : dataset.directorates.find(item => item.id === selectedDirectorate); return source ? { label: dataset.period.label.split(' ')[0], period: dataset.period.label, value: source.monthly || 0 } : null; }).filter(Boolean); const total = rows.reduce((sum, row) => sum + row.value, 0); document.querySelector('#currentMonth').innerHTML = rows.map(row => `<div class="month-row"><div><strong>${row.label}</strong><span>${row.period}</span></div><b>${compact(row.value)}</b></div>`).join('') + (rows.length ? `<div class="month-row"><div><strong>Akumulasi periode berjalan</strong><span>Bukan realisasi kumulatif resmi</span></div><b>${compact(total)}</b></div>` : ''); }
function setDirectorate(id) { selectedDirectorate = id; document.querySelector('#directorateSelect').value = id; selectedCompositionScope = id === 'all' ? 'deputy' : id; selectedCompositionCategory = null; document.querySelector('#compositionScope').value = selectedCompositionScope; renderComposition(); renderKpis(); renderPerformance(); lineChart(); renderCurrentMonth(); }
function updateActivePeriod(period) { const label = period?.label || 'Belum ada data SAKTI'; document.querySelector('#sidebarPeriod').textContent = label; document.querySelector('#activePeriod').textContent = `• ${label}`; const currentLabel = document.querySelector('#currentMonthPeriod'); if (currentLabel) currentLabel.textContent = label; document.querySelector('#progressYear').textContent = period?.year ? `TAHUN ${period.year}` : 'BELUM ADA DATA'; document.querySelector('#updatedAt').textContent = activeSnapshot ? `Terakhir diperbarui: ${new Date().toLocaleDateString('id-ID')}` : 'Unggah laporan SAKTI untuk mulai'; }
function enterYearlyView(year) { const snapshots = loadSnapshots(); const keys = sortedSnapshotKeys(snapshots).filter(key => key.startsWith(`${year}-`) && snapshotDataset(snapshots[key])); const key = keys.at(-1); if (!key) return; yearlyView = { year, latest: snapshotDataset(snapshots[key]).period }; const bucket = snapshots[key]; applySaktiDataset(snapshotDataset(bucket), bucket.sp2d.filename, false, 'sp2d'); document.querySelector('#monthSelect').value = 'yearly'; document.querySelector('#sidebarPeriod').textContent = `Tahunan ${year}`; document.querySelector('#activePeriod').textContent = `• Tahunan ${year} · s.d. ${yearlyView.latest.label}`; renderCurrentMonth(); lineChart(); }
function groupDrillAccounts(accounts) { return Object.values(accounts.reduce((groups, row) => { const key = `${row.accountCode}::${row.accountName}`; const group = groups[key] || { accountCode: row.accountCode, accountName: row.accountName, pagu: 0, cumulative: 0, accrualOutstanding: 0, potential: 0, remaining: 0, roCount: 0 }; group.pagu += row.pagu || 0; group.cumulative += row.cumulative ?? row.realization ?? 0; group.accrualOutstanding += row.accrualOutstanding || 0; group.potential += row.potential ?? row.cumulative ?? row.realization ?? 0; group.remaining += row.remaining ?? ((row.pagu || 0) - (row.cumulative ?? row.realization ?? 0)); group.roCount++; groups[key] = group; return groups; }, {})); }
function renderCompositionDetail() { const detail = document.querySelector('#compositionDetail'); const category = activeComposition()[selectedCompositionScope]?.categories.find(item => item.category === selectedCompositionCategory); if (!category || !category.accounts.length) { detail.hidden = true; detail.innerHTML = ''; return; } const isPotential = selectedCompositionMetric === 'potential'; const accounts = groupDrillAccounts(category.accounts); detail.hidden = false; detail.innerHTML = `<div class="detail-heading"><div><span class="eyebrow">RINCIAN AKUN</span><h3>${category.category}</h3></div><button class="detail-close" type="button" aria-label="Tutup rincian kategori">×</button></div><div class="composition-table-scroll"><table><thead><tr><th>Akun</th><th>Uraian</th>${isPotential ? '<th>SP2D</th><th>Akrual Berjalan</th><th>Potensi</th>' : '<th>Pagu</th><th>Realisasi SP2D</th><th>Sisa</th>'}</tr></thead><tbody>${accounts.map(account => `<tr><td><strong>${account.accountCode}</strong></td><td>${account.accountName}${account.roCount > 1 ? `<br><small>${account.roCount} RO terkait</small>` : ''}</td>${isPotential ? `<td>${rupiah.format(account.cumulative)}</td><td>${rupiah.format(account.accrualOutstanding)}</td><td><strong>${rupiah.format(account.potential)}</strong></td>` : `<td>${rupiah.format(account.pagu)}</td><td>${rupiah.format(account.cumulative)}</td><td><strong>${rupiah.format(account.remaining)}</strong></td>`}</tr>`).join('')}</tbody></table></div>`; detail.querySelector('.detail-close').addEventListener('click', () => { selectedCompositionCategory = null; renderCompositionDetail(); }); }
