function selectDashboardPeriod(value) { const periodSelect = document.querySelector('#monthSelect'); if (value === 'yearly') { periodMode = 'yearly'; enterYearlyView(Number(document.querySelector('#yearSelect').value)); return; } periodMode = 'monthly'; yearlyView = null; activeSnapshotKey = value; setActiveSnapshot(value); const activeMonthKey = activeSnapshot?.period ? snapshotKey(activeSnapshot.period) : null; if (periodSelect.value !== activeSnapshotKey || activeMonthKey !== activeSnapshotKey) console.error('PERIOD STATE MISMATCH', periodSelect.value, activeSnapshot?.period); }
