function populateSnapshotFilters(snapshots, activeKey) { const keys = sortedSnapshotKeys(snapshots).filter(key => snapshotDataset(snapshots[key])); if (!keys.length) return; const yearSelect = document.querySelector('#yearSelect'), monthSelect = document.querySelector('#monthSelect'), activeYear = Number(activeKey.slice(0, 4)); const years = [...new Set(keys.map(key => key.slice(0, 4)))]; yearSelect.innerHTML = years.map(year => `<option value="${year}" ${Number(year) === activeYear ? 'selected' : ''}>${year}</option>`).join(''); const monthKeys = keys.filter(key => key.startsWith(`${activeYear}-`)); monthSelect.innerHTML = monthKeys.map(key => `<option value="${key}" ${key === activeKey && periodMode !== 'yearly' ? 'selected' : ''}>${snapshotDataset(snapshots[key]).period.label.split(' ')[0]}</option>`).join('') + `<option value="yearly" ${periodMode === 'yearly' ? 'selected' : ''}>Tahunan</option>`; }
