async function startCloudSnapshots() { if (!window.SaktiCloud?.configured || !window.SaktiCloud.isAuthenticated()) return; try { const cloudSnapshots = await window.SaktiCloud.loadSnapshots(); const cloudKeys = sortedSnapshotKeys(cloudSnapshots); if (cloudKeys.length) { saveSnapshots(cloudSnapshots); setActiveSnapshot(cloudKeys.at(-1)); return; } window.SaktiCloud.status('Cloud terhubung; belum ada snapshot.'); } catch (error) { console.warn('Supabase snapshot fallback', error); window.SaktiCloud.status('Mode offline: menggunakan data tersimpan di perangkat'); const cached = loadSnapshots(); if (sortedSnapshotKeys(cached).length) setActiveSnapshot(sortedSnapshotKeys(cached).at(-1)); } }
function setAuthenticatedUi(user) { document.querySelector('#authScreen').hidden = true; document.querySelector('#appShell').hidden = false; document.querySelector('#currentUser').textContent = user?.email || ''; }
function setLoggedOutUi() { activeSnapshot = null; executiveSummary = { pagu: 0, realization: 0, monthly: 0, change: null }; directorates = []; accountDetails = []; budgetComposition = {}; localStorage.removeItem('saktiSnapshots'); document.querySelector('#appShell').hidden = true; document.querySelector('#authScreen').hidden = false; document.querySelector('#cloudStatus').textContent = ''; }
async function bootAuthentication() { const authScreen = document.querySelector('#authScreen'); authScreen.querySelector('h1').insertAdjacentHTML('afterend', '<p id="authLoading">Memeriksa sesi...</p>'); const session = await window.SaktiCloud.restoreSession(); if (session?.user) { setAuthenticatedUi(session.user); document.querySelector('#authLoading')?.remove(); startCloudSnapshots(); } else { document.querySelector('#authLoading')?.remove(); setLoggedOutUi(); } }
document.querySelector('#loginForm').addEventListener('submit', async event => { event.preventDefault(); const error = document.querySelector('#loginError'); error.hidden = true; try { const session = await window.SaktiCloud.signIn(document.querySelector('#loginEmail').value, document.querySelector('#loginPassword').value); setAuthenticatedUi(session.user); startCloudSnapshots(); } catch (cause) { console.error('Supabase login failed', cause); error.textContent = /invalid login|invalid credentials/i.test(cause.message) ? 'Email atau kata sandi tidak sesuai.' : 'Gagal terhubung ke server. Coba kembali.'; error.hidden = false; } });
